// Editor tool sinh tilemap cho tầng 2 (rừng). Chạy: Tools > Culinaria > Paint Floor 2.
// Chạy lại nhiều lần được: mỗi lần sẽ xoá và vẽ lại Grid_F2 + F2_Markers.
// Dữ liệu ô được sinh sẵn (tile của dungeontilesetfull 1, tự nối viền theo ô kề).
#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.Tilemaps;

public static class F2TilemapPainter
{
    const string TilePath = "Assets/TileMap/dungeontilesetfull 1_{0}.asset";

    [MenuItem("Tools/Culinaria/Paint Floor 2")]
    public static void Paint()
    {
        // Sorting lấy theo Tilemap nền cũ của scene để đồng bộ
        string sortLayer = "Default"; int baseOrder = 0; int groundLayer = 6;
        var oldGround = GameObject.Find("Grid/Tilemap");
        if (oldGround != null)
        {
            var r = oldGround.GetComponent<TilemapRenderer>();
            if (r != null) { sortLayer = r.sortingLayerName; baseOrder = r.sortingOrder; }
            groundLayer = oldGround.layer;
        }

        var old = GameObject.Find("Grid_F2");
        if (old != null) Undo.DestroyObjectImmediate(old);
        var oldMk = GameObject.Find("F2_Markers");
        if (oldMk != null) Undo.DestroyObjectImmediate(oldMk);

        var gridGo = new GameObject("Grid_F2", typeof(Grid));
        Undo.RegisterCreatedObjectUndo(gridGo, "Paint Floor 2");

        var back  = MakeLayer(gridGo, "F2_DecorBack", 0, sortLayer, baseOrder - 1);
        var swamp = MakeLayer(gridGo, "F2_Swamp", 0, sortLayer, baseOrder);
        var ground = MakeLayer(gridGo, "F2_Ground", groundLayer, sortLayer, baseOrder);
        var plat  = MakeLayer(gridGo, "F2_Platform", groundLayer, sortLayer, baseOrder);
        var front = MakeLayer(gridGo, "F2_DecorFront", 0, sortLayer, baseOrder + 1);

        AddSolidCollider(ground.gameObject, false);
        AddSolidCollider(plat.gameObject, true);
        swamp.gameObject.tag = "DeadZone";
        var swampCol = swamp.gameObject.AddComponent<TilemapCollider2D>();
        swampCol.isTrigger = true;           // Player.OnTriggerEnter2D bắt tag DeadZone

        int missing = 0;
        missing += Fill(back, BACK);
        missing += Fill(swamp, SWAMP);
        missing += Fill(ground, GROUND);
        missing += Fill(plat, PLATFORM);
        missing += Fill(front, FRONT);

        var mkRoot = new GameObject("F2_Markers");
        Undo.RegisterCreatedObjectUndo(mkRoot, "Paint Floor 2");
        foreach (var e in MARKERS.Split(';'))
        {
            var p = e.Split(',');
            var m = new GameObject(p[0]);
            m.transform.SetParent(mkRoot.transform);
            m.transform.position = new Vector3(int.Parse(p[1]) + 0.5f, int.Parse(p[2]) + 0.5f, 0);
        }

        EditorSceneManager.MarkSceneDirty(gridGo.scene);
        Debug.Log("[F2TilemapPainter] Đã vẽ tầng 2. Tile thiếu: " + missing);
    }

    static Tilemap MakeLayer(GameObject grid, string name, int layer, string sortLayer, int order)
    {
        var go = new GameObject(name, typeof(Tilemap), typeof(TilemapRenderer));
        go.transform.SetParent(grid.transform, false);
        go.layer = layer;
        var r = go.GetComponent<TilemapRenderer>();
        r.sortingLayerName = sortLayer;
        r.sortingOrder = order;
        return go.GetComponent<Tilemap>();
    }

    static void AddSolidCollider(GameObject go, bool oneWay)
    {
        var rb = go.AddComponent<Rigidbody2D>();
        rb.bodyType = RigidbodyType2D.Static;
        var tc = go.AddComponent<TilemapCollider2D>();
#if UNITY_2023_1_OR_NEWER
        tc.compositeOperation = Collider2D.CompositeOperation.Merge;
#else
        tc.usedByComposite = true;
#endif
        var comp = go.AddComponent<CompositeCollider2D>();
        if (oneWay)
        {
            var eff = go.AddComponent<PlatformEffector2D>();
            eff.useOneWay = true;
            eff.surfaceArc = 160f;
            comp.usedByEffector = true;
        }
    }

    static int Fill(Tilemap map, string data)
    {
        var cache = new Dictionary<int, TileBase>();
        var pos = new List<Vector3Int>(); var tiles = new List<TileBase>();
        int missing = 0;
        foreach (var e in data.Split(';'))
        {
            var p = e.Split(',');
            int id = int.Parse(p[2]);
            if (!cache.TryGetValue(id, out var t))
            {
                t = AssetDatabase.LoadAssetAtPath<TileBase>(string.Format(TilePath, id));
                cache[id] = t;
                if (t == null) { missing++; Debug.LogWarning("Thiếu tile " + id); }
            }
            if (t == null) continue;
            pos.Add(new Vector3Int(int.Parse(p[0]), int.Parse(p[1]), 0));
            tiles.Add(t);
        }
        map.SetTiles(pos.ToArray(), tiles.ToArray());
        map.CompressBounds();
        return missing;
    }

